import Foundation

extension Recipe {
    static let wrap = "\n\nText:\n\"\"\"\n{{input}}\n\"\"\""

    public static let builtins: [Recipe] = [
        // MARK: Understand
        Recipe(id: "summarize", title: "Summarize", summary: "Summary in your chosen style and length. Handles long documents.",
               symbol: "text.append", category: "Understand",
               instructions: "You summarize text accurately. Use only facts that appear in the text. Never add information. Keep the text's certainty: what it plans, proposes or lists as not yet done stays planned in the summary.",
               template: "Summarize the text as {{style}}. Length: {{length}} (short: at most 5 bullets or 3 sentences; medium: at most 10 bullets or 6 sentences; detailed: as long as the text needs)." + wrap,
               params: [RecipeParam(key: "style", label: "Style", defaultValue: "bullet points", choices: ["bullet points", "a paragraph", "an executive summary", "a one-line TL;DR"]),
                        RecipeParam(key: "length", label: "Length", defaultValue: "short", choices: ["short", "medium", "detailed"])],
               temperature: 0.3, permissive: true, long: .reduce, builtin: true, maxBullets: ["short": 5, "medium": 10], maxSentences: ["short": 3, "medium": 6]),
        Recipe(id: "key-points", title: "Key points", summary: "The five to eight points that matter most.",
               symbol: "list.star", category: "Understand",
               instructions: "You find the most important points in text. Be specific. Use only the text.",
               template: "List the 5 to 8 most important points in the text as short bullet points." + wrap,
               temperature: 0.3, permissive: true, long: .reduce, builtin: true),
        Recipe(id: "eli5", title: "Explain simply", summary: "Explains the text so a twelve-year-old would get it.",
               symbol: "graduationcap", category: "Understand",
               instructions: "You explain complex ideas in plain, friendly language with a concrete everyday example.",
               template: "Explain what this text is about in simple terms a twelve-year-old would understand." + wrap,
               temperature: 0.5, permissive: true, long: .reduce, builtin: true),
        Recipe(id: "ask", title: "Ask the document", summary: "Answers a question using only the text you give it.",
               symbol: "questionmark.bubble", category: "Understand",
               instructions: "Answer questions using only the provided text. If the text doesn't contain the answer, say \"The text doesn't say.\"",
               template: "Question: {{question}}" + wrap,
               params: [RecipeParam(key: "question", label: "Question", defaultValue: "What is the main conclusion?")],
               temperature: 0.2, permissive: true, long: .reduce, builtin: true),
        Recipe(id: "outline", title: "Outline", summary: "A clean hierarchical outline of the content.",
               symbol: "list.bullet.indent", category: "Understand",
               instructions: "You produce clear, hierarchical Markdown outlines of documents.",
               template: "Create a nested Markdown outline of this text with short headings." + wrap,
               temperature: 0.3, permissive: true, long: .reduce, builtin: true),

        // MARK: Write
        Recipe(id: "rewrite", title: "Rewrite", summary: "Rewrites text in a new tone while keeping the meaning.",
               symbol: "pencil.and.outline", category: "Write",
               instructions: "You rewrite text in the requested tone. Keep every fact and the original meaning, and add nothing the text doesn't have, such as a subject line. Output only the rewritten text.",
               template: "Rewrite the text in a {{tone}} tone." + wrap,
               params: [RecipeParam(key: "tone", label: "Tone", defaultValue: "professional",
                                    choices: ["professional", "friendly", "concise", "formal", "casual", "persuasive", "plain English", "enthusiastic"])],
               temperature: 0.6, permissive: true, long: .concatenate, builtin: true),
        Recipe(id: "proofread", title: "Proofread", summary: "Fixes spelling, grammar and punctuation. Returns the corrected text.",
               symbol: "checkmark.seal", category: "Write",
               instructions: "You are a meticulous copy editor. Fix spelling, grammar and punctuation only, including pronoun case, subject-verb agreement and run-on sentences. Pronouns that do the action take subject case: \"Me and him has been\" becomes \"He and I have been\". Keep the author's voice and wording otherwise. Output only the corrected text.",
               template: "Proofread and correct this text." + wrap,
               temperature: 0.1, permissive: true, long: .concatenate, builtin: true),
        Recipe(id: "translate", title: "Translate", summary: "Translates into any of the model's supported languages.",
               symbol: "character.bubble", category: "Write",
               instructions: "You are a professional translator. Translate faithfully and naturally. Output only the translation.",
               template: "Translate this text into {{language}}." + wrap,
               params: [RecipeParam(key: "language", label: "Language", defaultValue: "Spanish",
                                    choices: ["Spanish", "French", "German", "Italian", "Portuguese", "Japanese", "Korean", "Chinese (Simplified)", "Dutch", "Swedish", "Turkish", "Vietnamese", "Danish", "Norwegian", "English"])],
               temperature: 0.2, permissive: true, long: .concatenate, builtin: true),
        Recipe(id: "title", title: "Headlines", summary: "Five title or headline options.",
               symbol: "textformat.size", category: "Write",
               instructions: "You write sharp, accurate titles. No clickbait.",
               template: "Write 5 title options for this text, one per line, numbered, without quotation marks." + wrap,
               temperature: 0.8, permissive: true, long: .reduce, builtin: true),
        Recipe(id: "email-reply", title: "Email reply", summary: "Drafts a reply to an email with the intent you choose.",
               symbol: "arrowshape.turn.up.left", category: "Write",
               instructions: "You write clear, polite, brief email replies. Output only the email body: no subject line.",
               template: "Write a reply to this email. Intent: {{intent}}." + wrap,
               params: [RecipeParam(key: "intent", label: "Intent", defaultValue: "accept",
                                    choices: ["accept", "decline politely", "ask for more information", "say thank you", "propose a different time"])],
               temperature: 0.6, permissive: true, long: .reject, builtin: true),

        Recipe(id: "draft", title: "Draft from notes", summary: "Turns rough notes into a paragraph, email or short report.",
               symbol: "square.and.pencil", category: "Write",
               instructions: "You turn rough notes into clear, finished writing. Use every point in the notes and add nothing they don't contain: no names, dates, numbers, promises or claims of your own. Where the notes are unclear, leave the point out rather than guess. Output only the draft.",
               template: "Turn these notes into {{format}}." + wrap,
               params: [RecipeParam(key: "format", label: "Format", defaultValue: "a paragraph",
                                    choices: ["a paragraph", "an email", "a short report", "a chat message", "bullet points"])],
               temperature: 0.5, permissive: true, long: .reject, builtin: true),
        Recipe(id: "redact", title: "Redact", summary: "Hides names, addresses, emails, phone numbers and ID numbers behind placeholders.",
               symbol: "eye.slash", category: "Write",
               instructions: "You find personal details to hide. List every person's name, as written each time it appears (full name, first name or last name), and every street or mailing address exactly as written, the whole address through the city, state and postcode. Don't list organizations, products, job titles, or cities and countries on their own.",
               template: "List the people and addresses in this text." + wrap,
               schema: #"{"type":"object","title":"PersonalDetails","properties":{"people":{"type":"array","items":{"type":"string"},"description":"Names of people, exactly as written"},"addresses":{"type":"array","items":{"type":"string"},"description":"Whole street or mailing addresses, through the city, state and postcode, exactly as written"}},"required":["people","addresses"],"x-order":["people","addresses"]}"#,
               temperature: 0.0, permissive: true, long: .merge, builtin: true, transform: .redact),

        // MARK: Extract (structured)
        Recipe(id: "sentiment", title: "Sentiment", summary: "Sentiment label, confidence and a one-line reason, as JSON.",
               symbol: "face.smiling", category: "Extract",
               instructions: "You analyze the sentiment of text carefully and calibrate your confidence.",
               template: "Analyze the sentiment of this text." + wrap,
               params: [],
               schema: #"{"type":"object","title":"Sentiment","properties":{"sentiment":{"type":"string","enum":["positive","neutral","negative","mixed"]},"confidence":{"type":"number","minimum":0,"maximum":1},"reason":{"type":"string","description":"One short sentence"}},"required":["sentiment","confidence","reason"],"x-order":["sentiment","confidence","reason"]}"#,
               temperature: 0.1, permissive: true, long: .merge, builtin: true),
        Recipe(id: "classify", title: "Classify", summary: "Picks the best label from your own list, as JSON.",
               symbol: "tray.2", category: "Extract",
               instructions: "You classify text into exactly one of the allowed labels.",
               template: "Classify this text. Allowed labels: {{labels}}." + wrap,
               params: [RecipeParam(key: "labels", label: "Labels (comma-separated)", defaultValue: "bug report, feature request, question, praise, complaint")],
               schema: #"{"type":"object","title":"Classification","properties":{"label":{"type":"string","enum":{{labels_json}}},"confidence":{"type":"number","minimum":0,"maximum":1},"reason":{"type":"string"}},"required":["label","confidence","reason"],"x-order":["label","confidence","reason"]}"#,
               temperature: 0.1, permissive: true, long: .merge, builtin: true),
        Recipe(id: "entities", title: "Entities", summary: "People, organizations, places, dates and products, as JSON.",
               symbol: "person.2.crop.square.stack", category: "Extract",
               instructions: "You extract named entities exactly as they appear in the text. Don't invent any.",
               template: "Extract the named entities from this text." + wrap,
               schema: #"{"type":"object","title":"Entities","properties":{"people":{"type":"array","items":{"type":"string"}},"organizations":{"type":"array","items":{"type":"string"}},"places":{"type":"array","items":{"type":"string"}},"dates":{"type":"array","items":{"type":"string"}},"products":{"type":"array","items":{"type":"string"}}},"required":["people","organizations","places","dates","products"],"x-order":["people","organizations","places","dates","products"]}"#,
               temperature: 0.1, permissive: true, long: .merge, builtin: true),
        Recipe(id: "action-items", title: "Action items", summary: "Tasks with owner, due date and priority, as JSON.",
               symbol: "checklist", category: "Extract",
               instructions: "You find concrete action items in notes, emails and transcripts. Only list tasks that are actually stated.",
               template: "Extract every action item from this text." + wrap,
               schema: #"{"type":"object","title":"ActionItems","properties":{"items":{"type":"array","items":{"type":"object","title":"ActionItem","properties":{"task":{"type":"string"},"owner":{"type":"string","description":"Person responsible, or unassigned"},"due":{"type":"string","description":"Due date if stated, otherwise none"},"priority":{"type":"string","enum":["high","medium","low"]}},"required":["task","owner","due","priority"],"x-order":["task","owner","due","priority"]}}},"required":["items"]}"#,
               temperature: 0.1, permissive: true, long: .merge, builtin: true),
        Recipe(id: "meeting-notes", title: "Meeting notes", summary: "Summary, decisions, action items and open questions from a transcript.",
               symbol: "person.3.sequence", category: "Extract",
               instructions: "You turn meeting transcripts into structured notes. Use only what was said.",
               template: "Turn this meeting transcript into structured notes." + wrap,
               schema: #"{"type":"object","title":"MeetingNotes","properties":{"summary":{"type":"string","description":"Two or three sentences"},"decisions":{"type":"array","items":{"type":"string"}},"action_items":{"type":"array","items":{"type":"object","title":"MeetingAction","properties":{"task":{"type":"string"},"owner":{"type":"string"}},"required":["task","owner"],"x-order":["task","owner"]}},"open_questions":{"type":"array","items":{"type":"string"}}},"required":["summary","decisions","action_items","open_questions"],"x-order":["summary","decisions","action_items","open_questions"]}"#,
               temperature: 0.2, permissive: true, long: .merge, builtin: true),
        Recipe(id: "tags", title: "Tags", summary: "Topic tags using Apple's content-tagging model.",
               symbol: "tag", category: "Extract",
               instructions: "Tag the text with short, lowercase topic tags.",
               template: "{{input}}",
               params: [RecipeParam(key: "max_tags", label: "Maximum tags", defaultValue: "6", choices: ["3", "6", "10"])],
               schema: #"{"type":"object","title":"Tags","properties":{"tags":{"type":"array","maxItems":{{max_tags}},"items":{"type":"string"}}},"required":["tags"]}"#,
               temperature: 0.1, useCase: .tagging, permissive: true, long: .merge, builtin: true),
        Recipe(id: "keywords", title: "Keywords", summary: "Search keywords and key phrases, as JSON.",
               symbol: "magnifyingglass", category: "Extract",
               instructions: "You pick the keywords and phrases someone would search for to find this text.",
               template: "Extract up to 12 keywords or key phrases from this text." + wrap,
               schema: #"{"type":"object","title":"Keywords","properties":{"keywords":{"type":"array","maxItems":12,"items":{"type":"string"}}},"required":["keywords"]}"#,
               temperature: 0.2, permissive: true, long: .merge, builtin: true),
        Recipe(id: "quiz", title: "Quiz", summary: "Study questions with answers, as JSON.",
               symbol: "brain.head.profile", category: "Extract",
               instructions: "You write clear study questions whose answers are found in the text.",
               template: "Write {{count}} quiz questions with short answers based on this text." + wrap,
               params: [RecipeParam(key: "count", label: "Questions", defaultValue: "5", choices: ["3", "5", "8"])],
               schema: #"{"type":"object","title":"Quiz","properties":{"questions":{"type":"array","maxItems":10,"items":{"type":"object","title":"QuizItem","properties":{"question":{"type":"string"},"answer":{"type":"string"}},"required":["question","answer"],"x-order":["question","answer"]}}},"required":["questions"]}"#,
               temperature: 0.5, permissive: true, long: .merge, builtin: true),

        // MARK: Code
        Recipe(id: "explain-code", title: "Explain code", summary: "What a piece of code does, step by step.",
               symbol: "chevron.left.forwardslash.chevron.right", category: "Code",
               instructions: "You are a senior engineer. Explain code accurately and concisely. Don't invent behavior that isn't in the code.",
               template: "Explain what this code does, then list any obvious risks." + "\n\nCode:\n```\n{{input}}\n```",
               temperature: 0.2, permissive: true, long: .reduce, builtin: true),
        Recipe(id: "explain-error", title: "Explain an error", summary: "What went wrong in an error message, stack trace or log, and what to try.",
               symbol: "exclamationmark.triangle", category: "Code",
               instructions: "You read error messages, stack traces and logs. Use only what is in the output. In one sentence say what failed, quoting only the single line that names the error, such as the exception line. Then give the most likely cause, and one to three concrete next steps that inspect or check something, such as a log to read, a service to check or a setting to verify. Never suggest a command that dumps, deletes, resets or changes data. If the output doesn't show the cause, say so instead of guessing.",
               template: "Explain this error or log." + "\n\nOutput:\n```\n{{input}}\n```",
               temperature: 0.2, permissive: true, long: .tail, builtin: true),
        Recipe(id: "commit-message", title: "Commit message", summary: "A Conventional Commits message from a diff.",
               symbol: "point.topleft.down.to.point.bottomright.curvepath", category: "Code",
               instructions: "You write Conventional Commits messages: a type(scope): subject line under 72 characters, a blank line, then a short body of bullet points. Output only the message. Use feat for new behavior and fix for broken behavior; the scope names a module, not a file.",
               template: "Write a commit message for this diff." + "\n\nDiff:\n```\n{{input}}\n```",
               temperature: 0.2, permissive: true, long: .reduce, builtin: true),
        Recipe(id: "regex", title: "Regex helper", summary: "Builds a regular expression from a plain-English description.",
               symbol: "asterisk", category: "Code",
               instructions: "You write correct regular expressions. Anchor the pattern with ^ and $ unless asked to find matches inside longer text. Give the bare pattern alone on the first line, with no code fence or quotes, then one line explaining it.",
               template: "Write a regular expression that matches: {{input}}",
               temperature: 0.1, long: .reject, builtin: true),
    ]
}
